import{_ as l,a0 as i,w as p,s as r,ao as g,I as o,x as s,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"配置 logrotate 的终极指导 | LCTT x X-CMD","titleTemplate":false,"description":"配置 logrotate 的终极指导 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"配置 logrotate 的终极指导 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"配置 logrotate 的终极指导 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170122 Ultimate guide to configure logrotate utility","title":"配置 logrotate 的终极指导","tag":"201702","desc":""},"relativePath":"201702/20170122 Ultimate guide to configure logrotate utility.md","filePath":"[post].md"}'),d={name:"201702/20170122 Ultimate guide to configure logrotate utility.md"};function c(u,t,h,k,m,b){const a=i("Link");return p(),r("div",null,[t[13]||(t[13]=g(`<h1 id="配置-logrotate-的终极指导" tabindex="-1">配置 logrotate 的终极指导 <a class="header-anchor" href="#配置-logrotate-的终极指导" aria-label="Permalink to “配置 logrotate 的终极指导”">​</a></h1><p>一般来说，日志是任何故障排除过程中非常重要的一部分，但这些日志会随着时间增长。在这种情况下，我们需要手动执行日志清理以回收空间，这是一件繁琐的管理任务。为了解决这个问题，我们可以在 Linux 中配置 logrotate 程序，它可以自动执行日志文件的轮换、压缩、删除和用邮件发出。</p><p>我们可以配置 logrotate 程序，以便每个日志文件可以在每天、每周、每月或当它变得太大时处理。</p><h3 id="logrotate-是如何工作的" tabindex="-1">logrotate 是如何工作的 <a class="header-anchor" href="#logrotate-是如何工作的" aria-label="Permalink to “logrotate 是如何工作的”">​</a></h3><p>默认情况下，logrotate 命令作为放在 <code>/etc/cron.daily</code> 中的 cron 任务，每天运行一次，它会帮助你设置一个策略，其中超过某个时间或大小的日志文件被轮换。</p><p>命令： <code>/usr/sbin/logrotate</code></p><p>配置文件： <code>/etc/logrotate.conf</code></p><p>这是 logrotate 的主配置文件。logrotate 还在 <code>/etc/logrotate.d/</code> 中存储了特定服务的配置。确保下面的那行包含在 <code>/etc/logrotate.conf</code> 中，以读取特定服务日志配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>include  /etc/logrotate.d\`</span></span></code></pre></div><p>logrotate 历史： <code>/var/lib/logrotate.status</code></p><p>重要的 logrotate 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>compress             --&gt; 压缩日志文件的所有非当前版本</span></span>
<span class="line"><span>daily,weekly,monthly --&gt; 按指定计划轮换日志文件</span></span>
<span class="line"><span>delaycompress        --&gt; 压缩所有版本，除了当前和下一个最近的</span></span>
<span class="line"><span>endscript            --&gt; 标记 prerotate 或 postrotate 脚本的结束</span></span>
<span class="line"><span>errors &quot;emailid&quot;     --&gt; 给指定邮箱发送错误通知</span></span>
<span class="line"><span>missingok            --&gt; 如果日志文件丢失，不要显示错误</span></span>
<span class="line"><span>notifempty           --&gt; 如果日志文件为空，则不轮换日志文件</span></span>
<span class="line"><span>olddir &quot;dir&quot;         --&gt; 指定日志文件的旧版本放在 “dir” 中</span></span>
<span class="line"><span>postrotate           --&gt; 引入一个在日志被轮换后执行的脚本</span></span>
<span class="line"><span>prerotate            --&gt; 引入一个在日志被轮换前执行的脚本</span></span>
<span class="line"><span>rotate &#39;n&#39;           --&gt; 在轮换方案中包含日志的 n 个版本</span></span>
<span class="line"><span>sharedscripts        --&gt; 对于整个日志组只运行一次脚本</span></span>
<span class="line"><span>size=&#39;logsize&#39;       --&gt; 在日志大小大于 logsize（例如 100K，4M）时轮换</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>让我们为我们自己的示例日志文件 <code>/tmp/sample_output.log</code> 配置 logrotate。</p><p>第一步：在 <code>/etc/logrotate.conf</code> 中添加以下行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/tmp/sample_output.log {</span></span>
<span class="line"><span>  size 1k</span></span>
<span class="line"><span>  create 700 root root</span></span>
<span class="line"><span>  rotate 4</span></span>
<span class="line"><span>  compress</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的配置文件中：</p><ul><li>size 1k - logrotate 仅在文件大小等于（或大于）此大小时运行。</li><li>create - 轮换原始文件并创建具有指定权限、用户和组的新文件。</li><li>rotate - 限制日志文件轮转的数量。因此，这将只保留最近的 4 个轮转的日志文件。</li><li>compress - 这将压缩文件。</li></ul><p>第二步：通常，你需要等待一天才能等到 logrotate 由 <code>/etc/cron.daily</code> 执行。除此之外，你可以用下面的命令在命令行中运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/sbin/logrotate  /etc/logrotate.conf</span></span></code></pre></div><p>在执行 logrotate 命令之前的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 tmp]# ls -l /tmp/</span></span>
<span class="line"><span>total 28</span></span>
<span class="line"><span>-rw-------. 1 root root 20000 Jan 1 05:23 sample_output.log</span></span></code></pre></div><p>在执行 logrotate 之后的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 tmp]# ls -l /tmp</span></span>
<span class="line"><span>total 12</span></span>
<span class="line"><span>-rwx------. 1 root root 0 Jan 1 05:24 sample_output.log</span></span>
<span class="line"><span>-rw-------. 1 root root 599 Jan 1 05:24 sample_output.log-20170101.gz</span></span>
<span class="line"><span>[root@rhel1 tmp]#</span></span></code></pre></div><p>这样就能确认 logrotate 成功实现了。</p><hr><p>作者简介：</p><p>大家好！我是 Manmohan Mirkar。我很高兴见到你们！我在 10 多年前开始使用 Linux，我从来没有想过我会到今天这个地步。我的激情是帮助你们获取 Linux 知识。谢谢你们在这！</p><hr>`,29)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),e(a,{href:"http://www.linuxroutes.com/configure-logrotate/"},{default:n(()=>[...t[0]||(t[0]=[s("http://www.linuxroutes.com/configure-logrotate/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=s("作者：",-1)),e(a,{href:"http://www.linuxroutes.com/author/admin/"},{default:n(()=>[...t[2]||(t[2]=[s("Manmohan Mirkar",-1)])]),_:1}),t[6]||(t[6]=s(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:n(()=>[...t[3]||(t[3]=[s("geekpi",-1)])]),_:1}),t[7]||(t[7]=s(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[s("Linux中国",-1)])]),_:1}),t[12]||(t[12]=s(" 荣誉推出",-1))])])}const C=l(d,[["render",c]]);export{x as __pageData,C as default};
